					o.installTicks++
					if !recoveryModeEmitted[o.id] {
						recoveryModeEmitted[o.id] = true
						caSend(t, map[string]interface{}{
							"event":                        "recovery_mode_entered",
							"node":                         o.id,
							"applied_at_mode_entry":        app,
